//! Spec §9 test vectors for the encrypted file backup (format v1).
//!
//! Implements `docs/specs/encrypted-file-backup.md` (ratified v1.0, commit
//! 0592280) §9: five vectors (+ a magic-flip companion case) generated BY the
//! reference implementation from a fixed set of test keys — never
//! hand-computed — and checked in under `docs/backup-test-vectors/`. An
//! independent implementer validates against these.
//!
//! Reproducibility contract: every vector is a pure function of the fixed
//! test keys, fixed passwords, fixed salt/nonce, and the implementation
//! (`crate::backup::encrypt_deterministic`). The regeneration tests re-derive
//! each checked-in artifact and assert byte-identity; if the container
//! implementation ever changes its output, these vectors MUST be regenerated
//! deliberately (via the ignored generator test below) and re-reviewed as a
//! format event, because they are the compliance artifact.
//!
//! Each vector states: Argon2id params, salt, nonce, cipher_id, and the
//! derived AEAD key — the last so implementers can debug KDF drift
//! independently of AEAD issues (§9).

use serde::{Deserialize, Serialize};

use crate::api::structs::network::Network;
use crate::backup::{
    self, BackupError, ARGON2_DEFAULT_M_KIB, ARGON2_DEFAULT_P, ARGON2_DEFAULT_T,
    CIPHER_XCHACHA20_POLY1305,
};
use crate::backup_payload::{
    build_bip139_export, build_payload, build_secrets_block, BackupCoin, Bip352Labels,
    WalletScanState,
};

/// Fixed test scan secret (§9: vectors come from a fixed set of test keys).
pub const TEST_SCAN_SECRET: [u8; 32] = [0x11; 32];
/// Fixed test spend secret (§9).
pub const TEST_SPEND_SECRET: [u8; 32] = [0x22; 32];
/// Fixed salt for all vectors, 16 bytes (§3.3).
pub const TEST_SALT: [u8; 16] = *b"vector-salt-0001";
/// Fixed nonce for all vectors, 24 bytes (§3.3, XChaCha consumes all 24).
pub const TEST_NONCE: [u8; 24] = *b"vector-nonce-00000000001";
/// Password for vector 1 (policy-valid per §6.1).
pub const V1_PASSWORD: &str = "minimal backup vector 1";
/// Password for vectors 2, 3, 5 and 5a (policy-valid per §6.1).
pub const V2_PASSWORD: &str = "standard two-section vector 2";
/// Policy-valid but WRONG password for vector 4 (§9 vector 4).
pub const WRONG_PASSWORD: &str = "policy valid wrong password 4";

/// `cipher_id` for every v1 vector: XChaCha20-Poly1305, the only v1 writer
/// cipher (§3.4).
pub const VECTOR_CIPHER_ID: u8 = CIPHER_XCHACHA20_POLY1305;

// -- JSON artifact schema (checked in as docs/backup-test-vectors/vector-N.json)

/// Machine-readable vector artifact, exactly what is checked in under
/// `docs/backup-test-vectors/`. All hex fields are lowercase, byte order as
/// serialized.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct VectorArtifact {
    /// Stable id, e.g. `dana-backup-v1-vector-1`.
    pub vector_id: String,
    /// Short title (§9 numbering).
    pub title: String,
    /// Spec citation this vector fulfils.
    pub spec_reference: String,
    /// What the vector exercises.
    pub description: String,
    /// Password used in the vector (§6.1 policy-valid). For vector 4 this is
    /// the deliberately WRONG password.
    pub password: String,
    /// The password that actually decrypts `file_hex` (differs from
    /// `password` only for vector 4).
    pub file_password: String,
    /// Only for derived vectors (4, 5, 5a): the base vector id + mutation.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub derived_from: Option<DerivedFrom>,
    pub cipher_id: u8,
    pub cipher_name: String,
    pub argon2: Argon2Params,
    pub salt_hex: String,
    pub nonce_hex: String,
    pub nonce_len: u8,
    /// Derived AEAD key (§9: for KDF-drift debugging).
    pub derived_aead_key_hex: String,
    /// Full cleartext header bytes (the exact AAD region, §3.1).
    pub header_hex: String,
    /// Decrypted plaintext: the framed §5 sections.
    pub plaintext_hex: String,
    /// Complete file bytes: header || ciphertext || tag (§3.1).
    pub file_hex: String,
    /// Expected result when decrypting `file_hex` with `password`.
    pub expected: Expected,
}

/// Provenance for vectors 4, 5, 5a (each is vector 2 plus a defined mutation).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DerivedFrom {
    pub base_vector: String,
    /// Human-readable mutation applied to the base file.
    pub mutation: String,
    /// Byte offset of the mutation within the file.
    pub header_offset: usize,
    /// Bit flipped (XOR mask is `1 << bit`).
    pub bit: u32,
}

/// Argon2id parameters as serialized in the header (§3.3/§4).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Argon2Params {
    pub m_kib: u32,
    pub t: u32,
    pub p: u32,
}

/// Expected decrypt outcome. Error codes are the
/// [`BackupError`](crate::backup::BackupError) variant names — the defined
/// error codes of this implementation (§9 vectors 4–5).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Expected {
    /// `decrypt_success` or `decrypt_error`.
    pub outcome: String,
    /// Error code for `decrypt_error` outcomes.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error_code: Option<String>,
    /// §9 vector 4: AEAD failure must expose no partial plaintext.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub no_partial_plaintext: Option<bool>,
}

// -- Fixed test keys -> descriptors (reference implementation, §9) --

fn test_scan_secret() -> spdk_wallet::bitcoin::secp256k1::SecretKey {
    spdk_wallet::bitcoin::secp256k1::SecretKey::from_slice(&TEST_SCAN_SECRET)
        .expect("32-byte test scan secret")
}

fn test_spend_secret() -> spdk_wallet::bitcoin::secp256k1::SecretKey {
    spdk_wallet::bitcoin::secp256k1::SecretKey::from_slice(&TEST_SPEND_SECRET)
        .expect("32-byte test spend secret")
}

/// Watch-only `sp()` scan descriptor built the same way the wallet API builds
/// them (`SpKey::Scan` form) — this is what the §5.1 BIP-139 section carries.
pub fn test_watch_only_descriptor() -> String {
    use spdk_wallet::bitcoin::key::Secp256k1;
    use spdk_wallet::silentpayments::Network as SpNetwork;

    let spend_pk = test_spend_secret().public_key(&Secp256k1::signing_only());
    let key = bip392::SpKey::Scan(bip392::SpScanKey {
        scan_key: test_scan_secret(),
        spend_key: spend_pk,
        network: SpNetwork::Mainnet,
    });
    bip392::Sp::from_sp_key(key).to_string()
}

/// Full encoded `sp()` spend descriptor (`SpKey::Spend` form, D11) — what the
/// §5.2 secrets block carries. Never serialized into the BIP-139 section.
pub fn test_full_spend_descriptor() -> String {
    use spdk_wallet::silentpayments::Network as SpNetwork;

    let key = bip392::SpKey::Spend(bip392::SpSpendKey {
        scan_key: test_scan_secret(),
        spend_key: test_spend_secret(),
        network: SpNetwork::Mainnet,
    });
    bip392::Sp::from_sp_key(key).to_string()
}

// -- §5 payload builders, one per plaintext shape --

/// Vector 1: minimal — smallest valid BIP-139 export (single `bip392`
/// account, no labels, no coins) + the REQUIRED secrets block, no optional
