// -- Vector generation --

fn hex(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        use std::fmt::Write as _;
        let _ = write!(s, "{b:02x}");
    }
    s
}

struct BaseVector {
    id: &'static str,
    title: &'static str,
    spec_reference: &'static str,
    description: String,
    password: &'static str,
    payload: Vec<u8>,
}

fn base_vector(n: u8) -> BaseVector {
    match n {
        1 => BaseVector {
            id: "dana-backup-v1-vector-1",
            title: "Minimal payload",
            spec_reference: "docs/specs/encrypted-file-backup.md §9 vector 1",
            description: "Smallest valid file: minimal BIP-139 export (single bip392 account, \
                          no labels) + REQUIRED secrets block, no optional section."
                .into(),
            password: V1_PASSWORD,
            payload: vector1_payload(),
        },
        2 => BaseVector {
            id: "dana-backup-v1-vector-2",
            title: "With secrets block (standard two-section file)",
            spec_reference: "docs/specs/encrypted-file-backup.md §9 vector 2",
            description: "Standard two-section file: BIP-139 payload with scan state \
                          (last_height, bip352_labels, coins) + secrets block carrying the \
                          full test sp() spend descriptor."
                .into(),
            password: V2_PASSWORD,
            payload: vector2_payload(),
        },
        3 => BaseVector {
            id: "dana-backup-v1-vector-3",
            title: "With optional section (all three sections)",
            spec_reference: "docs/specs/encrypted-file-backup.md §9 vector 3",
            description: "All three sections present, exercising companion fields (§5.3; \
                          schema deferred, body is a placeholder UTF-8 JSON document)."
                .into(),
            password: V2_PASSWORD,
            payload: vector3_payload(),
        },
        other => panic!("no base vector {other}"),
    }
}

fn seal(vector: &BaseVector) -> (Vec<u8>, [u8; 32], Vec<u8>) {
    let file = backup::encrypt_deterministic(
        VECTOR_CIPHER_ID,
        ARGON2_DEFAULT_M_KIB,
        ARGON2_DEFAULT_T,
        ARGON2_DEFAULT_P,
        &TEST_SALT,
        &TEST_NONCE,
        &vector.payload,
        vector.password,
    )
    .expect("deterministic encryption of a valid payload");
    let key = backup::derive_aead_key(
        vector.password.as_bytes(),
        &TEST_SALT,
        ARGON2_DEFAULT_M_KIB,
        ARGON2_DEFAULT_T,
        ARGON2_DEFAULT_P,
    )
    .expect("default KDF params are valid");
    let header = file[..backup::HEADER_BASE_LEN].to_vec();
    (file, key, header)
}

/// Builds the checked-in artifact for vectors 1–3.
pub fn generate_base_artifact(n: u8) -> VectorArtifact {
    let vector = base_vector(n);
    let (file, key, header) = seal(&vector);
    VectorArtifact {
        vector_id: vector.id.into(),
        title: vector.title.into(),
        spec_reference: vector.spec_reference.into(),
        description: vector.description.clone(),
        password: vector.password.into(),
        file_password: vector.password.into(),
        derived_from: None,
        cipher_id: VECTOR_CIPHER_ID,
        cipher_name: "XChaCha20-Poly1305".into(),
        argon2: Argon2Params {
            m_kib: ARGON2_DEFAULT_M_KIB,
            t: ARGON2_DEFAULT_T,
            p: ARGON2_DEFAULT_P,
        },
        salt_hex: hex(&TEST_SALT),
        nonce_hex: hex(&TEST_NONCE),
        nonce_len: 24,
        derived_aead_key_hex: hex(&key),
        header_hex: hex(&header),
        plaintext_hex: hex(&vector.payload),
        file_hex: hex(&file),
        expected: Expected {
            outcome: "decrypt_success".into(),
            error_code: None,
            no_partial_plaintext: None,
        },
    }
}

/// Vector 4: wrong-password decrypt of vector 2 (§9). Policy-valid wrong
/// password; AEAD tag mismatch, no partial plaintext, error code
/// `AuthenticationFailed`.
pub fn generate_vector4() -> VectorArtifact {
    let base = base_vector(2);
    let (file, key, header) = seal(&base);
    VectorArtifact {
        vector_id: "dana-backup-v1-vector-4".into(),
        title: "Wrong-password decryption failure".into(),
        spec_reference: "docs/specs/encrypted-file-backup.md §9 vector 4".into(),
        description: "Vector 2 decrypted with a policy-valid but wrong password: AEAD tag \
                      mismatch, no partial plaintext exposed, defined error code."
            .into(),
        password: WRONG_PASSWORD.into(),
        file_password: base.password.into(),
        derived_from: Some(DerivedFrom {
            base_vector: "dana-backup-v1-vector-2".into(),
            mutation: "none (same file as vector 2; only the password differs)".into(),
            header_offset: 0,
            bit: 0,
        }),
        cipher_id: VECTOR_CIPHER_ID,
        cipher_name: "XChaCha20-Poly1305".into(),
        argon2: Argon2Params {
            m_kib: ARGON2_DEFAULT_M_KIB,
            t: ARGON2_DEFAULT_T,
            p: ARGON2_DEFAULT_P,
        },
        salt_hex: hex(&TEST_SALT),
        nonce_hex: hex(&TEST_NONCE),
        nonce_len: 24,
        derived_aead_key_hex: hex(&key),
        header_hex: hex(&header),
        plaintext_hex: hex(&base.payload),
        file_hex: hex(&file),
        expected: Expected {
            outcome: "decrypt_error".into(),
            error_code: Some("AuthenticationFailed".into()),
            no_partial_plaintext: Some(true),
        },
    }
}

/// Vector 5 + companion: corrupted-header-AAD failures of vector 2 (§9). One
/// flipped bit in a non-magic header byte (`argon2_t`) fails AEAD
/// verification against the tampered AAD (`AuthenticationFailed`); the
/// companion flips a magic bit and documents the early parse-reject path
/// (`BadMagic`, §3.2).
pub fn generate_vector5(with_companion: bool) -> VectorArtifact {
    let base = base_vector(2);
    let (mut file, key, header) = seal(&base);
    let (offset, bit, mutation, id_suffix, title_suffix, error_code) = if with_companion {
        (
            0usize,
            0u32,
            "flipped bit 0 of header byte 0x00 (magic[0], 'D')",
            "a",
            "corrupted magic (early parse-reject)",
            "BadMagic",
        )
    } else {
        (
            0x14usize,
            0u32,
            "flipped bit 0 of header byte 0x14 (argon2_t low byte)",
            "",
            "corrupted header AAD (argon2_t)",
            "AuthenticationFailed",
        )
    };
    file[offset] ^= 1 << bit;
    let expected_error = if with_companion {
        BackupError::BadMagic
    } else {
        BackupError::AuthenticationFailed
    };
    let artifact = VectorArtifact {
        vector_id: format!("dana-backup-v1-vector-5{id_suffix}"),
        title: format!(
            "{} — {title_suffix}",
            if with_companion {
                "Companion: corrupted magic bytes"
            } else {
                "Corrupted-header-AAD decryption failure"
            }
        ),
        spec_reference: format!(
            "docs/specs/encrypted-file-backup.md §9 vector 5{} (§3.2)",
            if with_companion { " companion" } else { "" }
        ),
        description: if with_companion {
            "Vector 2 with one flipped bit in the magic bytes: rejected before any further \
             parsing (early parse-reject path, §3.2), defined error code."
                .into()
        } else {
            "Vector 2 with one flipped bit in a non-magic header byte (argon2_t): tag \
             verification fails against the tampered AAD, no partial plaintext, defined \
             error code."
                .into()
        },
        password: base.password.into(),
        file_password: base.password.into(),
        derived_from: Some(DerivedFrom {
            base_vector: "dana-backup-v1-vector-2".into(),
            mutation: mutation.into(),
            header_offset: offset,
            bit,
        }),
        cipher_id: VECTOR_CIPHER_ID,
        cipher_name: "XChaCha20-Poly1305".into(),
        argon2: Argon2Params {
            m_kib: ARGON2_DEFAULT_M_KIB,
            t: ARGON2_DEFAULT_T,
            p: ARGON2_DEFAULT_P,
        },
        salt_hex: hex(&TEST_SALT),
        nonce_hex: hex(&TEST_NONCE),
        nonce_len: 24,
        derived_aead_key_hex: hex(&key),
        header_hex: hex(&header),
        plaintext_hex: hex(&base.payload),
        file_hex: hex(&file),
        expected: Expected {
            outcome: "decrypt_error".into(),
            error_code: Some(error_code.into()),
            no_partial_plaintext: Some(!with_companion),
        },
    };
    // The error code stated in the artifact must match the real error the
    // mutation produces, so the artifact cannot drift from the implementation.
    assert_eq!(artifact.expected.error_code.as_deref(), Some(err_name(&expected_error)));
    artifact
}

fn err_name(err: &BackupError) -> &'static str {
    match err {
        BackupError::TruncatedFile => "TruncatedFile",
        BackupError::BadMagic => "BadMagic",
        BackupError::UnsupportedFormatVersion(_) => "UnsupportedFormatVersion",
        BackupError::UnsupportedCipherId(_) => "UnsupportedCipherId",
        BackupError::InvalidNonceLen { .. } => "InvalidNonceLen",
        BackupError::NonZeroReserved => "NonZeroReserved",
        BackupError::NewerVersion => "NewerVersion",
        BackupError::TruncatedPayload => "TruncatedPayload",
        BackupError::AuthenticationFailed => "AuthenticationFailed",
        BackupError::InvalidKdfParams(_) => "InvalidKdfParams",
        BackupError::EntropySource(_) => "EntropySource",
    }
}

/// All six artifacts, in §9 order (5a is the §9 vector 5 companion case).
pub fn all_artifacts() -> Vec<VectorArtifact> {
    vec![
        generate_base_artifact(1),
        generate_base_artifact(2),
        generate_base_artifact(3),
        generate_vector4(),
        generate_vector5(false),
        generate_vector5(true),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::backup_payload::validate_bip139_export;

    /// Checked-in artifacts, compile-time embedded so the tests never depend
    /// on the working directory.
    const CHECKED_IN: &[&str] = &[
        include_str!("../../docs/backup-test-vectors/vector-1.json"),
        include_str!("../../docs/backup-test-vectors/vector-2.json"),
        include_str!("../../docs/backup-test-vectors/vector-3.json"),
        include_str!("../../docs/backup-test-vectors/vector-4.json"),
        include_str!("../../docs/backup-test-vectors/vector-5.json"),
        include_str!("../../docs/backup-test-vectors/vector-5a.json"),
    ];

    fn regenerate(artifact: &VectorArtifact) -> VectorArtifact {
        match artifact.vector_id.as_str() {
            "dana-backup-v1-vector-1" => generate_base_artifact(1),
            "dana-backup-v1-vector-2" => generate_base_artifact(2),
            "dana-backup-v1-vector-3" => generate_base_artifact(3),
            "dana-backup-v1-vector-4" => generate_vector4(),
            "dana-backup-v1-vector-5" => generate_vector5(false),
            "dana-backup-v1-vector-5a" => generate_vector5(true),
            other => panic!("unknown vector id {other}"),
        }
    }

    fn hex_to_bytes(s: &str) -> Vec<u8> {
        (0..s.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
            .collect()
    }

    /// §9 acceptance 1: the BIP-139 section of every vector validates as a
    /// standalone BIP-139 export (§5.1/D2), the secrets block carries the
    /// full test descriptor, and section presence matches the vector shape.
    #[test]
    fn vector_payloads_are_compliant() {
        for n in 1..=3u8 {
            let payload = base_vector(n).payload;
            let sections = crate::backup_payload::parse_sections(&payload).unwrap();
            assert_eq!(sections[0].0, crate::backup_payload::SECTION_TYPE_BIP139);
            assert_eq!(sections[1].0, crate::backup_payload::SECTION_TYPE_SECRETS);
            let bip139 = std::str::from_utf8(&sections[0].1).unwrap();
            validate_bip139_export(bip139).unwrap();
            let descriptor = crate::backup_payload::parse_secrets_block(
                std::str::from_utf8(&sections[1].1).unwrap(),
            )
            .unwrap();
            assert_eq!(descriptor, test_full_spend_descriptor());
            if n == 3 {
                assert_eq!(sections[2].0, crate::backup_payload::SECTION_TYPE_COMPANION);
            } else {
                assert_eq!(sections.len(), 2, "vector {n} has no optional section");
            }
        }
    }

    /// §9 acceptance 2: every checked-in artifact regenerates byte-identical
    /// from the reference implementation, metadata included.
    #[test]
    fn checked_in_vectors_regenerate_byte_identical() {
        for json in CHECKED_IN {
            let checked_in: VectorArtifact =
                serde_json::from_str(json).expect("checked-in artifact parses");
            assert_eq!(
                &regenerate(&checked_in),
                &checked_in,
                "{} drifted from the reference implementation",
                checked_in.vector_id
            );
        }
    }

    /// §9 acceptance 3 (vector 4): wrong password -> AEAD tag mismatch, no
    /// partial plaintext, defined error code.
    #[test]
    fn vector4_wrong_password_error_code() {
        let artifact: VectorArtifact = serde_json::from_str(CHECKED_IN[3]).unwrap();
        let file = hex_to_bytes(&artifact.file_hex);
        let err = backup::decrypt(&file, &artifact.password).unwrap_err();
        assert_eq!(err, BackupError::AuthenticationFailed);
        assert_eq!(artifact.expected.error_code.as_deref(), Some("AuthenticationFailed"));
        assert_eq!(artifact.expected.no_partial_plaintext, Some(true));
    }

    /// §9 acceptance 3 (vector 5 + companion): corrupted header AAD ->
    /// `AuthenticationFailed`; corrupted magic -> `BadMagic` before parsing.
    #[test]
    fn vector5_corrupt_header_error_codes() {
        for json in [CHECKED_IN[4], CHECKED_IN[5]] {
            let artifact: VectorArtifact = serde_json::from_str(json).unwrap();
            let file = hex_to_bytes(&artifact.file_hex);
            let err = backup::decrypt(&file, &artifact.password).unwrap_err();
            let expected = artifact.expected.error_code.as_deref().unwrap();
            assert_eq!(err_name(&err), expected, "{}", artifact.vector_id);
        }
    }

    /// The derived AEAD key stated in each vector really is the key the
    /// implementation derives (KDF-drift debugging aid, §9).
    #[test]
    fn stated_aead_key_matches_implementation() {
        for json in CHECKED_IN {
            let artifact: VectorArtifact = serde_json::from_str(json).unwrap();
            let salt: [u8; 16] = hex_to_bytes(&artifact.salt_hex).try_into().unwrap();
            let key = backup::derive_aead_key(
                artifact.file_password.as_bytes(),
                &salt,
                artifact.argon2.m_kib,
                artifact.argon2.t,
                artifact.argon2.p,
            )
            .unwrap();
            assert_eq!(hex(&key), artifact.derived_aead_key_hex);
        }
    }

    /// Generator (§9: vectors MUST be produced by the reference
    /// implementation). Run:
    /// `DANA_VECTOR_OUT=<dir> cargo test --lib generate_artifacts -- --ignored --nocapture`
    #[test]
    #[ignore = "artifact generator: set DANA_VECTOR_OUT=<dir>"]
    fn generate_artifacts() {
        let Ok(dir) = std::env::var("DANA_VECTOR_OUT") else {
            return; // no-op without an explicit output dir
        };
        for artifact in all_artifacts() {
            let file_name = artifact.vector_id.trim_start_matches("dana-backup-v1-");
            let pretty =
                serde_json::to_string_pretty(&artifact).expect("artifact serializes");
            std::fs::write(format!("{dir}/{file_name}.json"), pretty + "\n")
                .expect("write artifact");
            println!("wrote {dir}/{file_name}.json");
        }
    }
}
